 "content": "def transform(grid):
    """Color the trailing background after a row's sole non-background run."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        nonbg = [i for i, value in enumerate(row) if value != bg]
        if not nonbg:
            continue
        # The colored pixels must form exactly one contiguous run of one color.
        lo, hi = nonbg[0], nonbg[-1]
        color = row[lo]
        if any(row[i] != color for i in range(lo, hi + 1)):
