 "content": "def transform(grid):
    """Complete selected row-end gaps after long runs or a repeated alternating motif."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        end = len(row) - 1
        while end >= 0 and row[end] == bg:
            end -= 1
        if end < 0:
            continue
        last_color = row[end]
        start = end
        while start >= 0 and row[start] == last_color:
            start -= 1
        final_run = end - start
        # Most demonstrations have a repeated final foreground run. Some show
        # a repeating two-color alternating line ending in a single marker;
        # the row-end continuation follows that same pattern.
        alternating = 0
        for c in range(end, 0, -1):
            if row[c] != row[c - 1]:
                alternating += 1
            else:
                break
        should_fill = final_run >= 2 or alternating >= 4
        # A shared multi-cell suffix on adjacent patterned rows is also a
        # demonstrated target case.
        suffix = len(row) - 1 - end
